/* The tag families Napa detects: upstream AprilTag's, as generated by gen_families.py into families/.
 *
 * Every family is a square `width` cells across whose outer ring of cells is the border, with a one-cell
 * quiet ring around it and data cells inside the square, and for some families outside the quiet ring
 * too. Classic families (tag16h5, tag25h9, tag36h10, tag36h11) print the border black on white. Reversed
 * families print it white inside a black frame, so Napa detects them on the inverted image, where they
 * look like a classic tag. */
#ifndef NAPA_FAMILIES_H
#define NAPA_FAMILIES_H

#include <stdint.h>

typedef struct {
    const char *name;
    int width;        /* cells across the detected square: the tag size pose solvers use */
    int total_width;  /* cells across the whole printed tag */
    int reversed;     /* the square prints light, in a dark frame */
    int min_distance; /* minimum Hamming distance between codes, rotations included */
    int nbits;
    int ncodes;
    const int8_t *x, *y;   /* each bit's cell, most significant first, relative to the square's top-left */
    const uint64_t *codes; /* a set bit is a white cell of the printed tag */
} napa_family;

#include "families/tag16h5.h"
#include "families/tag25h9.h"
#include "families/tag36h10.h"
#include "families/tag36h11.h"
#include "families/tagCircle21h7.h"
#include "families/tagCircle49h12.h"
#include "families/tagCustom48h12.h"
#include "families/tagStandard41h12.h"
#include "families/tagStandard52h13.h"

/* tag36h11 first: it is the default. */
static const napa_family napa_families[] = {
    NAPA_TAG36H11_FAMILY,         NAPA_TAG16H5_FAMILY,           NAPA_TAG25H9_FAMILY,
    NAPA_TAG36H10_FAMILY,         NAPA_TAGSTANDARD41H12_FAMILY,  NAPA_TAGSTANDARD52H13_FAMILY,
    NAPA_TAGCIRCLE21H7_FAMILY,    NAPA_TAGCIRCLE49H12_FAMILY,    NAPA_TAGCUSTOM48H12_FAMILY,
};
#define NAPA_FAMILY_COUNT ((int)(sizeof napa_families / sizeof napa_families[0]))

#endif
